// ======================================================================
// \title  ModeManagerTester.hpp
// \brief  hpp file for ModeManager component rule-based test harness
//
// connectPorts() is hand-written rather than generated by
// UT_AUTO_HELPERS so that checkTransition can be left unconnected on
// purpose. That is how the shipped default policy (permit everything)
// is exercised: with nothing connected to checkTransition, the
// component must fall back to it. A second constructor argument
// connects checkTransition for tests that exercise an external policy.
// ======================================================================

#ifndef Svc_ModeManagerTester_HPP
#define Svc_ModeManagerTester_HPP

#include "STest/Pick/Pick.hpp"
#include "Svc/ModeManager/ModeManager.hpp"
#include "Svc/ModeManager/ModeManagerGTestBase.hpp"
#include "Svc/ModeManager/test/ut/TestState/TestState.hpp"
#include "TestUtils/RuleBasedTesting.hpp"

namespace Svc {

class ModeManagerTester final : public ModeManagerGTestBase {
  public:
    // ----------------------------------------------------------------------
    // Constants
    // ----------------------------------------------------------------------

    //! Maximum size of histories storing events, telemetry, and port outputs.
    //! Must exceed NUM_SUBSCRIBERS (see ModeManagerCfg.fpp) since a single
    //! transition fans out to every connected modeChanged port.
    static const FwSizeType MAX_HISTORY_SIZE = 16;

    //! Instance ID supplied to the component instance under test
    static const FwEnumStoreType TEST_INSTANCE_ID = 0;

    //! Queue depth supplied to the component instance under test
    static const FwSizeType TEST_INSTANCE_QUEUE_DEPTH = 10;

    //! Number of modeChanged subscriber ports. Must match
    //! ModeManagerCfg.NUM_SUBSCRIBERS.
    static const FwIndexType NUM_SUBSCRIBERS = 8;

    //! Number of requestMode ports. Must match ModeManagerCfg.NUM_REQUESTERS.
    static const FwIndexType NUM_REQUESTERS = 4;

    //! requestMode port index 0 is reserved: Requester::NONE (value 0) means
    //! "no component requester" (the ground path). A real component
    //! requester must occupy index 1 or above so its Requester value is
    //! never confused with NONE. Tests that exercise the component path
    //! pick indices in [FIRST_REAL_REQUESTER, NUM_REQUESTERS).
    static const FwIndexType FIRST_REAL_REQUESTER = 1;

  public:
    // ----------------------------------------------------------------------
    // Construction and destruction
    // ----------------------------------------------------------------------

    //! Construct object ModeManagerTester
    //! \param connectExternalPolicy If true, wire checkTransition to this
    //!   tester so from_checkTransition_handler decides every transition.
    //!   If false (default), leave it unconnected so the component falls
    //!   back to its shipped default policy.
    explicit ModeManagerTester(bool connectExternalPolicy = false);

    //! Destroy object ModeManagerTester
    ~ModeManagerTester();

  private:
    // ----------------------------------------------------------------------
    // Helper functions
    // ----------------------------------------------------------------------

    //! Connect ports
    void connectPorts();

    //! Initialize components
    void initComponents();

  public:
    // ----------------------------------------------------------------------
    // Shared assertion helpers
    // ----------------------------------------------------------------------

    //! Dispatch exactly numMessages queued messages, asserting each one
    //! actually dispatches rather than silently doing fewer.
    //!
    //! There is no way to "drain until empty": the generated doDispatch()
    //! calls Os::Queue::receive() with BLOCKING, so calling it once more
    //! than there are messages hangs forever rather than returning
    //! MSG_DISPATCH_EMPTY. The caller must know the exact count instead:
    //!
    //!   - A command or port call that leads to an APPROVED transition
    //!     enqueues 2 messages: the call itself, then the signal it sends
    //!     to the mode machine (sending a signal enqueues rather than
    //!     running immediately -- see
    //!     docs/user-manual/framework/state-machines.md section 5.5.1).
    //!   - A call that is DENIED enqueues only 1: handleRequest() returns
    //!     before ever sending a signal.
    //!   - A call uninvolved with the mode machine (e.g. pingIn) enqueues
    //!     only 1.
    //!
    //! Telemetry, events, and the modeChanged/checkTransition ports are
    //! synchronous outputs, not queued messages -- they never add to the
    //! count.
    void dispatchExactly(FwSizeType numMessages);

    //! Assert that modeChanged fired on every connected subscriber with the
    //! given from/to pair, and nothing else
    void assertModeChangedBroadcast(Mode::T fromMode, Mode::T toMode);

    //! Assert the full set of side effects of a transition that the active
    //! policy permitted, then advance the shadow to match
    void assertPermittedTransition(Mode::T fromMode,
                                    Mode::T toMode,
                                    ModeRequestSource::T source,
                                    Requester::T requester);

    //! Assert the full set of side effects of a transition that the active
    //! policy denied: mode unchanged, TransitionRejected fired, no
    //! ModeTransitioned, no modeChanged calls
    void assertDeniedTransition(Mode::T requested,
                                 ModeRequestSource::T source,
                                 Requester::T requester,
                                 ModePolicySource::T decidedBy);

    //! Pick a uniformly random mode that is a legal signal target.
    //! STARTUP is excluded: nothing transitions into it.
    static Mode::T pickReachableMode();

  private:
    // ----------------------------------------------------------------------
    // Handler overrides
    // ----------------------------------------------------------------------

    //! Controllable stand-in for an external policy component. Records the
    //! call to history (matching the generated default) and returns
    //! m_policyResponse.
    Fw::Success from_checkTransition_handler(FwIndexType portNum,
                                              const Mode& current,
                                              const Mode& target,
                                              const ModeRequest& req) override;

  public:
    // ----------------------------------------------------------------------
    // Member variables
    // ----------------------------------------------------------------------

    //! The component under test
    ModeManager component;

    //! Shadow state for rule-based testing
    ModeManagerTestState shadow;

    //! Whether checkTransition was wired during construction
    const bool m_connectExternalPolicy;

    //! What from_checkTransition_handler returns when called. Tests that
    //! connect the external policy set this before invoking a transition.
    Fw::Success m_policyResponse = Fw::Success::SUCCESS;

    //! Monotonic command sequence number for sendCmd_* calls
    U32 m_cmdSeq = 0;

  public:
    // ----------------------------------------------------------------------
    // Rule Based Testing
    // ----------------------------------------------------------------------

    //! Ground command REQUEST_MODE, exercised against every reachable mode
    FW_RBT_DEFINE_RULE(ModeManagerTester, RequestModeCmd, Transition);

    //! Ground command REQUEST_MODE(STARTUP) -- STARTUP has no entry in
    //! ModeList.inc, so this is rejected before any policy is consulted
    FW_RBT_DEFINE_RULE(ModeManagerTester, RequestModeCmd, UnsupportedTarget);

    //! Component port requestMode[n], exercised against every reachable
    //! mode and every real requester port
    FW_RBT_DEFINE_RULE(ModeManagerTester, RequestModePort, Transition);

    //! requestMode[0] -- reserved, must be rejected before a ModeRequest
    //! is ever constructed
    FW_RBT_DEFINE_RULE(ModeManagerTester, RequestModePort, ReservedPort);

    //! Ground command START
    FW_RBT_DEFINE_RULE(ModeManagerTester, Start, ToIdle);

    //! Query the current mode via getMode
    FW_RBT_DEFINE_RULE(ModeManagerTester, GetMode, Query);

    //! Health ping round trip
    FW_RBT_DEFINE_RULE(ModeManagerTester, Ping, Check);

    // These three run only against a tester constructed with
    // connectExternalPolicy = true; they are not part of the default-policy
    // random scenario. See test/ut/Rules/ExternalPolicy.cpp.

    //! External policy permits a request
    FW_RBT_DEFINE_RULE(ModeManagerTester, ExternalPolicy, Permits);

    //! External policy denies a request
    FW_RBT_DEFINE_RULE(ModeManagerTester, ExternalPolicy, Denies);

    //! External policy denies a transition the default would always permit,
    //! proving precedence rather than mere consultation
    FW_RBT_DEFINE_RULE(ModeManagerTester, ExternalPolicy, DeniesEvenObviousTransition);
};

}  // namespace Svc

#endif
